"""Verify and summarize matched lens transfers generated by lensing.py."""
from pathlib import Path
import hashlib,json
import numpy as np
P=Path(__file__).resolve().parent; L=P.parent/'isotropic-galaxy-transfer'
old=json.loads((L/'third-retention-optics-results.json').read_text())
prior={(r['Name'],r['model']):r for r in old['rows']}
outputs={b:json.loads((L/('capacity-'+b+'-optics-results.json')).read_text()) for b in ['original','reference','local','recycling','reference-refined','recycling-refined']}
assert outputs['original']['summary']==old['summary']
out=dict(scope='Conditional six-lens comparison, shared amplitudes from SPARC training; lens inner-star mass and anisotropy fits retained; no new blind sample',rows=[],summary=[],refinement=[])
for branch,result in outputs.items():
    assert len(result['rows'])==12
    for row in result['rows']:
        ref=prior[row['Name'],row['model']]
        if branch=='original':
            for key,value in ref.items():assert row[key]==value
        assert row['observed_stellar_vrms']==ref['observed_stellar_vrms']
        assert row['geometry']==ref['geometry'] and row['retention_mapping']==ref['retention_mapping']
        assert row['lens_catalog_arcsec']==ref['lens_catalog_arcsec']
        assert row['optimizer_successes']>0
        assert not row['orbit_boundary']
        assert 1e7<row['mass_Msun']<1e14
        out['rows'].append(dict(branch=branch,Name=row['Name'],population=row['model'].split('_')[-1],
            lens_prediction_arcsec=row['lens_prediction_arcsec'],lens_catalog_arcsec=row['lens_catalog_arcsec'],
            lens_fractional_residual=row['lens_fractional_residual'],outer_standardized_residual=row['outer_conditional_standardized_residual'],
            stellar_mass_Msun=row['mass_Msun'],beta=row['beta'],inner_chi2=row['inner_chi2']))
    for summary in result['summary']:
        out['summary'].append(dict(branch=branch,C0_multiplier=result['C0_multiplier'],**summary))
for branch in ['reference','recycling']:
    coarse={(r['Name'],r['model']):r for r in outputs[branch]['rows']}
    fine=outputs[branch+'-refined']['rows']
    out['refinement'].append(dict(branch=branch,
        max_angle_change_arcsec=max(abs(r['lens_prediction_arcsec']-coarse[r['Name'],r['model']]['lens_prediction_arcsec']) for r in fine),
        max_outer_prediction_change_kms=max(abs(r['outer_prediction_kms']-coarse[r['Name'],r['model']]['outer_prediction_kms']) for r in fine),
        max_lens_fractional_RMS_change=max(abs(a['lens_fractional_rms']-b['lens_fractional_rms']) for a,b in zip(outputs[branch]['summary'],outputs[branch+'-refined']['summary']))))
out['paired_refined_lens_changes']=[]
for imf in ['Chabrier','Salpeter']:
    rr=[r for r in out['rows'] if r['population']==imf and r['branch']=='reference-refined']
    yy={r['Name']:r for r in out['rows'] if r['population']==imf and r['branch']=='recycling-refined'}
    out['paired_refined_lens_changes'].append(dict(population=imf,
        systems_with_smaller_absolute_lens_residual=sum(abs(yy[r['Name']]['lens_fractional_residual'])<abs(r['lens_fractional_residual']) for r in rr),systems=len(rr)))
paths=[L/'lensing.py',L/'third-retention-optics-results.json',L/'third-radiation-retention-results.json',P/'local-capacity-results.json',P/'conservative-recycling-results.json',
    P.parent/'slacs-component-refit/model.py',P.parent/'slacs-resolved-fit/model.py']
paths += [L/('capacity-'+b+'-optics-results.json') for b in outputs]
for folder,name in [('slacs-resolved-input-audit','results.json'),('slacs-motion-lensing-pilot','results.json'),('lensing-data-readiness','conditional-geometry.json'),('slacs-light-profile-audit','results.json'),('slacs-outer-bin-check','protocol.json'),('slacs-outer-bin-check','results.json'),('lens-photometric-audit','normalization-sensitivity.json'),('brightness-distance-consistency','regular-area-results.json'),('lensing-data-readiness','lens-observations-and-image-models.json')]:
    paths.append(P.parent/folder/name)
out['input_sha256']={str(f.relative_to(P.parents[2])).replace('\\','/'):hashlib.sha256(f.read_bytes()).hexdigest() for f in paths}
(P/'capacity-lensing-results.json').write_text(json.dumps(out,indent=2,allow_nan=False)+'\n',encoding='utf-8',newline='\n')
print(json.dumps(out['summary'],indent=2));print(json.dumps(out['refinement'],indent=2));print(out['paired_refined_lens_changes'])
